class ShoppingCart:
    def __init__(self):
        self._items = {}

    def add_item(self, item, price, quantity=1):
        self._items[item] = {'price': price, 'quantity': quantity}

    def remove_item(self, item, quantity=1):
        if item in self._items:
            self._items[item]['quantity'] -= quantity

    def view_items(self) -> dict:
        return self._items.copy()

    def total_price(self) -> float:
        return self._calculate_total_price()

    def _calculate_total_price(self) -> float:
        return sum(item['quantity'] * item['price'] for item in self._items.values())

    def get_items(self) -> dict:
        return self._items

    def set_items(self, items: dict):
        self._items = items
